115	        if (typed != null && !typed.isEmpty() && !AMOUNT.matcher(typed).matches()) {
116	            throw new InvalidSettingException("The clerk limit must be an amount of 0.00 or more, with up to two decimals.");
117	        }
118	        String terms = body == null || body.terms() == null ? "" : body.terms().trim();
119	        if (!terms.isEmpty() && !DAYS.matcher(terms).matches()) {
120	            throw new InvalidSettingException("The terms must be a whole number of days, 0 or more.");
121	        }
