133	                throw new InvalidSettingException("The pot must be an amount of 0.00 or more, with up to two decimals.");
134	            }
135	            pot = twoDecimals(pot);
136	        }
137	        String parent = body == null || body.parent() == null ? null : body.parent().trim();
138	        if (parent != null && !parent.isEmpty()) {
139	            String sheet = sheetId.trim();
140	            if (parent.equals(sheet)) {
141	                throw new InvalidSettingException("A sheet cannot be its own parent.");
142	            }
143	            if (!sheets.exists(parent)) {
144	                throw new InvalidSettingException("The parent must be a sheet that exists.");
145	            }
146	            java.util.Set<String> seen = new java.util.HashSet<>();
147	            for (String at = parent; !at.isEmpty() && seen.add(at); at = store.parent(at)) {
148	                if (at.equals(sheet)) {
149	                    throw new InvalidSettingException("The parent cannot be a sheet that has this sheet as an ancestor.");
150	                }
151	            }
152	        }
153	        String fiscalStartMonth = body == null || body.fiscalStartMonth() == null || body.fiscalStartMonth().isBlank() ? null
154	                : body.fiscalStartMonth().trim();
155	        if (fiscalStartMonth != null) {
156	            if (!MONTH.matcher(fiscalStartMonth).matches() || Integer.parseInt(fiscalStartMonth) < 1 || Integer.parseInt(fiscalStartMonth) > 12) {
157	                throw new InvalidSettingException("The fiscal year start month must be a month, 1 to 12.");
158	            }
159	            fiscalStartMonth = Integer.toString(Integer.parseInt(fiscalStartMonth));
160	        }
161	        Map<String, LocalDate> from = new java.util.HashMap<>();
162	        if (body != null && body.from() != null) {
163	            for (Map.Entry<String, String> entry : body.from().entrySet()) {
164	                String key = entry.getKey() == null ? "" : entry.getKey().trim();
165	                String date = entry.getValue() == null ? "" : entry.getValue().trim();
166	                if (date.isEmpty()) {
167	                    continue;
168	                }
169	                if (!Settings.DATED.contains(key)) {
170	                    throw new InvalidSettingException("Only a setting that carries a figure has a from-date.");
171	                }
172	                try {
173	                    from.put(key, LocalDate.parse(date));
174	                } catch (DateTimeParseException e) {
175	                    throw new InvalidSettingException("The from-date must be a date (yyyy-mm-dd).");
176	                }
177	            }
178	        }
179	        Map<String, String> perms = new java.util.LinkedHashMap<>();
180	        if (body != null && body.perms() != null) {
181	            for (String action : body.perms().keySet()) {
182	                if (!Settings.PERM_ACTIONS.contains(action)) {
183	                    throw new InvalidSettingException("Permissions are set only for open, settle, void, reassign, close and reopen.");
184	                }
185	            }
186	            for (String action : Settings.PERM_ACTIONS) {
187	                String typedRoles = body.perms().get(action);
188	                if (typedRoles == null) {
189	                    continue;
190	                }
191	                java.util.List<String> roles = new java.util.ArrayList<>();
192	                if (!typedRoles.isBlank()) {
193	                    for (String role : typedRoles.split(",")) {
194	                        String r = role.trim();
195	                        if (!Settings.ROLES.contains(r)) {
196	                            throw new InvalidSettingException("The roles allowed to " + action + " must be clerk or steward, separated by commas.");
197	                        }
198	                        if (!roles.contains(r)) {
199	                            roles.add(r);
200	                        }
201	                    }
202	                }
203	                perms.put(action, String.join(",", roles));
204	            }
205	        }
206	        boolean others = !floor.isEmpty() || !terms.isEmpty() || !gradeTerms.isEmpty() || !gradeGrace.isEmpty() || !gradeProof.isEmpty() || !latePct.isEmpty() || policyDate != null
207	                || numberingFrom != null || cap != null || threshold != null || noteThreshold != null || grace != null || entryDate != null || !perms.isEmpty() || pot != null || parent != null
208	                || fiscalStartMonth != null;
209	        if (typed == null && !others) {
210	            typed = "";
211	        }
212	        String limit = typed == null || (typed.isEmpty() && others) ? null
213	                : typed.isEmpty() ? "" : twoDecimals(typed);
214	        settingsOut.set(new SheetSettings(sheetId.trim(), limit, floor.isEmpty() ? null : twoDecimals(floor),
215	                terms.isEmpty() ? null : Integer.toString(Integer.parseInt(terms)),
216	                latePct.isEmpty() ? null : twoDecimals(latePct), policyDate, numberingFrom, cap, threshold, grace, noteThreshold, entryDate, gradeTerms, gradeGrace, from, perms, gradeProof, pot, parent, fiscalStartMonth));
217	    }
