255	        if (settings.proofThreshold() != null) {
256	            dated(settings, store, today, Settings.PROOF_THRESHOLD, settings.proofThreshold());
257	        }
258	        settings.gradeProof().forEach((grade, amount) -> dated(settings, store, today, Settings.gradeProofKey(grade), amount));
259	        if (settings.noteThreshold() != null) {
260	            dated(settings, store, today, Settings.NOTE_THRESHOLD, settings.noteThreshold());
261	        }
262	        if (settings.graceDays() != null) {
263	            store.set(settings.sheetId(), Settings.GRACE_DAYS, settings.graceDays());
264	        }
265	        settings.gradeGrace().forEach((grade, days) -> dated(settings, store, today, Settings.gradeGraceKey(grade), days));
266	        if (settings.entryDate() != null) {
267	            store.set(settings.sheetId(), Settings.ENTRY_DATE, settings.entryDate());
268	        }
269	        settings.perms().forEach((action, roles) -> store.set(settings.sheetId(), Settings.permKey(action), roles));
270	        if (settings.pot() != null) {
271	            store.set(settings.sheetId(), Settings.POT, settings.pot());
272	        }
